    const jsonData = pm.response.json();
    const requiredFields = ["id", "fimNumber", "nom", "prenom", "pays", "dateAnniversaire", "photo"];
    jsonData.forEach(function (rider) {
        requiredFields.forEach(function (field) {
            pm.expect(rider).to.have.property(field);
